// Optional online conformance probe. No target signer or transaction-send method;
// autogenerated local Ganache accounts are used only for local EVM comparison.
import fs from 'node:fs';
import crypto from 'node:crypto';
import solc from 'solc';
import ganache from 'ganache';
import { BrowserProvider,ContractFactory,Interface,keccak256 } from 'ethers';

const SOURCE_FILES=['contracts/math/Fixed96Math.sol','contracts/math/Fixed96EwaldMath.sol',
  ...['FixedPointNonbondedKernel','Fixed96SoftcoreLennardJonesKernel','Fixed96EwaldRealSpaceKernel','Fixed96EwaldReciprocalKernel','Fixed96LennardJonesKernel'].map(n=>`contracts/kernels/${n}.sol`)];
const NAMES=['FixedPointNonbondedKernel','Fixed96SoftcoreLennardJonesKernel','Fixed96EwaldRealSpaceKernel','Fixed96EwaldReciprocalKernel','Fixed96LennardJonesKernel'];
const ENDPOINT='https://robinhood.rpc.pinax.network',OUTPUT='reports/fixed96_target_execution.json';
const ALLOWED=new Set(['eth_chainId','eth_getBlockByNumber','eth_getCode','eth_getTransactionCount','eth_call']);
const sha256=x=>crypto.createHash('sha256').update(x).digest('hex');
const canonical=x=>Array.isArray(x)?'['+x.map(canonical).join(',')+']':x&&typeof x==='object'?'{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}':JSON.stringify(x);
const requireThat=(ok,msg)=>{if(!ok)throw new Error(msg);};
let serial=0;
const report={schemaVersion:1,status:'incomplete',startedAtUtc:new Date().toISOString(),
  scope:'Candidate fixed96 kernels only: source-compiled creation and numerical eth_call conformance against a local EVM at one pinned target-provider block.',
  limitations:['Provider responses are trusted, not independently verified state proofs.',
    'State overrides and creation eth_call are ephemeral simulations, not deployments or transaction-admission/fee measurements.',
    'Local-return equality checks execution conformance, not scientific correctness; the separate high-precision tests cover finite component fixtures.',
    'This does not validate the complete molecular engine, a prepared trajectory, sampling convergence, total cost or mainnet readiness.'],
  providerOrigin:ENDPOINT,targetChainId:4663,mainnetTransactionsSent:0,transactionSendMethodsAvailable:false,
  productionReady:false,networkReadAllowlist:[...ALLOWED],scriptSha256:sha256(fs.readFileSync(import.meta.filename)),
  requests:[],creationChecks:[],numericalChecks:[]};
const save=()=>fs.writeFileSync(OUTPUT,JSON.stringify(report,null,2)+'\n');
fs.mkdirSync('reports',{recursive:true});save();
async function rpc(method,params=[]){
  requireThat(ALLOWED.has(method),'Method outside read-only allowlist');
  const payload={jsonrpc:'2.0',id:++serial,method,params};
  const record={id:serial,method,requestSha256:sha256(canonical(payload))};report.requests.push(record);
  const response=await fetch(ENDPOINT,{method:'POST',redirect:'error',headers:{'content-type':'application/json'},body:JSON.stringify(payload),signal:AbortSignal.timeout(20000)});
  record.httpStatus=response.status;requireThat(response.ok,`${method}: HTTP ${response.status}`);
  const raw=await response.text();record.responseSha256=sha256(raw);requireThat(raw.length<2_000_000,'Oversized RPC result');
  const value=JSON.parse(raw);requireThat(value.id===payload.id&&value.jsonrpc==='2.0','RPC identity mismatch');
  if(value.error){record.error=value.error;throw new Error(`${method}: ${value.error.message}`);}
  requireThat(Object.hasOwn(value,'result'),'Missing RPC result');return value.result;
}
const transport=ganache.provider({logging:{quiet:true},chain:{chainId:31337,hardfork:'shanghai'}});
try{
  requireThat(solc.version().startsWith('0.8.26+'),'Wrong compiler version');
  const sources=Object.fromEntries(SOURCE_FILES.map(n=>[n,{content:fs.readFileSync(n,'utf8')}]));
  const settings={optimizer:{enabled:true,runs:200},evmVersion:'shanghai',outputSelection:{'*':{'*':['abi','evm.bytecode.object','evm.deployedBytecode.object','evm.deployedBytecode.immutableReferences']}}};
  const input={language:'Solidity',sources,settings},output=JSON.parse(solc.compile(JSON.stringify(input)));
  requireThat(!output.errors?.some(x=>x.severity==='error'),'Candidate compilation failed');
  Object.assign(report,{compiler:solc.version(),compilerSettings:settings,sourceSha256:Object.fromEntries(SOURCE_FILES.map(n=>[n,sha256(sources[n].content)])),standardInputSha256:sha256(canonical(input)),packageLockSha256:sha256(fs.readFileSync('package-lock.json'))});
  const artifacts={};for(const contracts of Object.values(output.contracts))for(const [name,a]of Object.entries(contracts))if(NAMES.includes(name))artifacts[name]=a;
  requireThat(Object.keys(artifacts).length===NAMES.length,'Incomplete compiled candidate set');
  requireThat(BigInt(await rpc('eth_chainId'))===4663n,'Wrong chain');
  const block=await rpc('eth_getBlockByNumber',['latest',false]);
  requireThat(/^0x[0-9a-f]+$/i.test(block.number)&&/^0x[0-9a-f]{64}$/i.test(block.hash),'Malformed reference block');
  report.referenceBlock={number:block.number,hash:block.hash,stateRoot:block.stateRoot,gasLimit:block.gasLimit};
  const sender='0x0000000000000000000000000000000000009100',gas='0x1c9c380';
  const nonce=await rpc('eth_getTransactionCount',[sender,block.number]);
  const provider=new BrowserProvider(transport),signer=await provider.getSigner(0),overrides={},local={};
  for(const [i,name]of NAMES.entries()){
    const a=artifacts[name],runtime='0x'+a.evm.deployedBytecode.object,creation='0x'+a.evm.bytecode.object;
    requireThat(Object.keys(a.evm.deployedBytecode.immutableReferences||{}).length===0,'Probe requires immutable-free runtime');
    const address='0x'+(0x9110+i).toString(16).padStart(40,'0');
    requireThat(await rpc('eth_getCode',[address,block.number])==='0x','Synthetic address already contains code');
    overrides[address]={code:runtime};
    const returned=await rpc('eth_call',[{from:sender,gas,gasPrice:'0x0',data:creation},block.number]);
    requireThat(returned.toLowerCase()===runtime.toLowerCase(),'Creation runtime mismatch');
    report.creationChecks.push({name,address,runtimeBytes:(runtime.length-2)/2,runtimeKeccak256:keccak256(runtime),passed:true});
    const c=await new ContractFactory(a.abi,creation,signer).deploy();await c.waitForDeployment();local[name]={address,localAddress:await c.getAddress(),iface:new Interface(a.abi)};
  }
  const z='0x00000000000000000000000000000000',one='0x3fff0000000000000000000000000000',half='0x3ffe0000000000000000000000000000',two='0x40000000000000000000000000000000',three='0x40008000000000000000000000000000';
  const cases=[
    [NAMES[0],'evaluate',[[one,half,z],half,one,half,one,two,three,false]],
    [NAMES[0],'evaluate',[[one,z,z],one,one,z,one,two,three,true]],
    [NAMES[1],'evaluate',[[half,half,z],[[half,one],[one,half],half,half]]],
    [NAMES[1],'evaluate',[[z,z,z],[[one,z],[half,one],'0x3ffec00000000000000000000000000000',half]]],
    [NAMES[2],'evaluate',[[one,half,z],half,one,two,three]],
    [NAMES[3],'structureFactorTerm',[[half,one,z],half,[1,-2,3],[three,three,three]]],
    [NAMES[3],'waveVector',[[1,-2,3],[three,three,three],two,one]],
    [NAMES[4],'evaluate',[[z,z,z],[one,z,z],one,one]]
  ];
  for(const [name,method,args]of cases){
    const a=local[name],data=a.iface.encodeFunctionData(method,args);
    const expected=await provider.call({to:a.localAddress,data});
    const actual=await rpc('eth_call',[{from:sender,to:a.address,data,gas,gasPrice:'0x0'},block.number,overrides]);
    requireThat(actual.toLowerCase()===expected.toLowerCase(),'Numerical target/local return mismatch');
    report.numericalChecks.push({name,method,calldata:data,expectedReturnData:expected,actualReturnData:actual,passed:true});
  }
  for(const a of Object.values(local))requireThat(await rpc('eth_getCode',[a.address,block.number])==='0x','Pinned-state code recheck differed');
  requireThat(await rpc('eth_getTransactionCount',[sender,block.number])===nonce,'Pinned nonce recheck differed');
  const recheck=await rpc('eth_getBlockByNumber',[block.number,false]);requireThat(recheck.hash===block.hash&&recheck.stateRoot===block.stateRoot,'Pinned block changed');
  for(const n of SOURCE_FILES)requireThat(sha256(fs.readFileSync(n))===report.sourceSha256[n],'Source changed during probe');
  report.status='passed';report.passed=true;
}catch(e){report.status='failed_or_unsupported';report.passed=false;report.error=e.message;process.exitCode=2;}
finally{transport.disconnect();report.completedAtUtc=new Date().toISOString();save();}
console.log(JSON.stringify({status:report.status,creationChecks:report.creationChecks.length,numericalChecks:report.numericalChecks.length,error:report.error}));
